diff --git a/source/standalone/defined-search-values.ts b/source/standalone/defined-search-values.ts
new file mode 100644
index 0000000..e8566ae
--- /dev/null
+++ b/source/standalone/defined-search-values.ts
@@ -0,0 +1,15 @@
+import is, {assert} from '@sindresorhus/is';
+
+/**
+Validate search parameter values without loading `Options`.
+
+Same as the validation used by `Options#searchParams`, except `undefined` values are rejected.
+*/
+export function validateDefinedSearchValues(searchParameters: Record<string, unknown>): asserts searchParameters is Record<string, string | number | boolean | null> { // eslint-disable-line @typescript-eslint/ban-types
+	// eslint-disable-next-line guard-for-in
+	for (const key in searchParameters) {
+		const value = searchParameters[key];
+
+		assert.any([is.string, is.number, is.boolean, is.null], value);
+	}
+}
diff --git a/test/defined-search-values.ts b/test/defined-search-values.ts
new file mode 100644
index 0000000..925b448
--- /dev/null
+++ b/test/defined-search-values.ts
@@ -0,0 +1,60 @@
+import test from 'ava';
+import {validateDefinedSearchValues} from '../source/standalone/defined-search-values.js';
+
+test('accepts strings, numbers, booleans and null', t => {
+	t.notThrows(() => {
+		validateDefinedSearchValues({
+			a: 'foo',
+			b: '',
+			c: 1,
+			d: -1.5,
+			e: true,
+			f: false,
+			g: null,
+		});
+	});
+});
+
+test('accepts empty input', t => {
+	t.notThrows(() => {
+		validateDefinedSearchValues({});
+	});
+});
+
+test('rejects undefined values', t => {
+	t.throws(() => {
+		validateDefinedSearchValues({a: 'foo', b: undefined});
+	}, {instanceOf: TypeError});
+});
+
+test('rejects non-scalar values', t => {
+	for (const value of [{}, [], () => {}, Symbol('x'), 1n, Number.NaN]) {
+		t.throws(() => {
+			validateDefinedSearchValues({a: value});
+		}, {instanceOf: TypeError});
+	}
+});
+
+test('validates inherited enumerable entries', t => {
+	const parent = {inherited: undefined};
+	const child = Object.create(parent) as Record<string, unknown>;
+	child.own = 'foo';
+
+	t.throws(() => {
+		validateDefinedSearchValues(child);
+	}, {instanceOf: TypeError});
+
+	const validChild = Object.create({inherited: 'bar'}) as Record<string, unknown>;
+	t.notThrows(() => {
+		validateDefinedSearchValues(validChild);
+	});
+});
+
+test('ignores non-enumerable entries', t => {
+	const object = {};
+	Object.defineProperty(object, 'hidden', {value: undefined, enumerable: false});
+
+	t.notThrows(() => {
+		validateDefinedSearchValues(object);
+	});
+});
